var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Gameplay/Main_Gameplay.unity",UnityEditor.SceneManagement.OpenSceneMode.Single);var panel=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t=>t.gameObject).FirstOrDefault(g=>g.name=="LevelUp_Panel");if(!panel)throw new System.Exception("LevelUp_Panel not found");var ui=panel.GetComponent<SoulHunter.Gameplay.UI.LevelUpUI>();if(!ui)throw new System.Exception("LevelUpUI not found");ui.enabled=true;UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);return new{scene=scene.path,levelUpUIEnabled=ui.enabled};
